"""Exact C393410 route entrypoint; CARLA loads only after source review."""
from __future__ import annotations

import argparse
import json
import os
from pathlib import Path

from route_measure import load_review

ASSIGNMENT='testing__C393410__LVMC-11-48-060__motor_vehicle_driver'
VARIANTS={'through_no_enroute':('non_truck','through','none'),'pickup_required':('non_truck','through','pick_up'),'delivery_required':('non_truck','through','delivery'),'essential_required':('non_truck','through','essential_use'),'local_non_through':('non_truck','local','none'),'designated_route':('truck_route','through','none')}
CAMERAS={'overview':[1920,1080],'approach':[1280,720],'reference_corner':[1280,720],'driver_reference':[1280,720]}


def check(root:Path)->dict:
    root=Path(root).resolve();config=json.loads((root/'config.json').read_text());spec=json.loads((root/'case-spec.json').read_text());control=json.loads((root/'controller.json').read_text());case_id=config.get('selected_case_id')
    if case_id not in {ASSIGNMENT+'__'+suffix for suffix in VARIANTS}:
        raise ValueError('Selected truck-route case differs')
    if (config.get('law_id'),config.get('cell_id'),config.get('actor'))!=('LVMC-11-48-060','C393410','motor_vehicle_driver') or spec.get('case_id')!=case_id:
        raise ValueError('Exact law, cell, actor or case differs')
    named={camera.get('name'):[camera.get('width'),camera.get('height')] for camera in config.get('cameras',[])}
    if config.get('rate_hz')!=20 or config.get('duration_s')!=45 or len(config.get('cameras',[]))!=4 or named!=CAMERAS:
        raise ValueError('Four synchronized 20 Hz views required')
    if tuple(spec.get(key) for key in ('street_class','route_use','enroute_purpose'))!=VARIANTS[case_id.split('__')[-1]]:
        raise ValueError('Selected route comparison variable differs')
    speed=control.get('target_speed_mps')
    if type(speed) not in (int,float) or not 1<=speed<=8:
        raise ValueError('Bounded original route speed required')
    return {'case_id':case_id,'speed':speed,'source_gate':'reviewed original municipal truck-route designations, non-truck connector, complete route and required enroute activity before Native'}


def main():
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');parser.add_argument('--output-dir',type=Path,default=Path.cwd());parser.add_argument('--packet',type=Path);parser.add_argument('--source-root',type=Path);parser.add_argument('--host',default='127.0.0.1');parser.add_argument('--port',type=int,default=2000);args=parser.parse_args()
    selected=check(args.output_dir)
    if args.check:
        print(json.dumps({**selected,'native_started':False}));return
    packet=args.packet or os.environ.get('C393410_ROUTE_REVIEW_PACKET');source_root=args.source_root or os.environ.get('C393410_ROUTE_SOURCE_ROOT')
    if not packet or not source_root:raise ValueError('Original reviewed route packet and source root required')
    load_review(Path(packet),Path(source_root),selected['case_id'])
    from native_entry import capture_original
    print(json.dumps(capture_original(args.output_dir,args.output_dir,packet,source_root,host=args.host,port=args.port),sort_keys=True))

if __name__=='__main__':main()

"""Capture source-reviewed passage between truck routes with world restoration."""
from __future__ import annotations

import hashlib
import json
import os
from pathlib import Path
from queue import Empty, Queue
import shutil
import subprocess

from route_measure import load_review, sha
from route_adapter import configure, step, sample, teardown

CAMERAS={'overview':(1920,1080),'approach':(1280,720),'reference_corner':(1280,720),'driver_reference':(1280,720)}


def write(path:Path,value:dict)->None:
    path.write_text(json.dumps(value,indent=2,sort_keys=True,allow_nan=False)+'\n')


def camera(world,carla,pose,name,queue):
    blueprint=world.get_blueprint_library().find('sensor.camera.rgb')
    width,height=CAMERAS[name]
    blueprint.set_attribute('image_size_x',str(width));blueprint.set_attribute('image_size_y',str(height));blueprint.set_attribute('sensor_tick','0.05')
    xyz,pyr=pose['location_xyz_m'],pose['pitch_yaw_roll_deg']
    actor=world.try_spawn_actor(blueprint,carla.Transform(carla.Location(*xyz),carla.Rotation(pitch=pyr[0],yaw=pyr[1],roll=pyr[2])))
    if actor is None:raise RuntimeError('Original truck-route camera spawn failed: '+name)
    actor.listen(lambda image:queue.put(image));return actor


def encoder(path,width,height):
    return subprocess.Popen(['ffmpeg','-hide_banner','-loglevel','error','-y','-f','rawvideo','-pixel_format','bgra','-video_size',f'{width}x{height}','-framerate','20','-i','pipe:0','-c:v','ffv1',str(path)],stdin=subprocess.PIPE,stdout=subprocess.DEVNULL,stderr=subprocess.PIPE)


def image(queue,expected):
    try:value=queue.get(timeout=15)
    except Empty as error:raise RuntimeError('Synchronized truck-route camera frame missing') from error
    if value.frame!=expected:raise ValueError('Original camera frame identity differs')
    return value


def capture_original(root,attempt,review_path,source_root,*,host='127.0.0.1',port=2000):
    root,attempt,review_path,source_root=map(lambda x:Path(x).resolve(),(root,attempt,review_path,source_root))
    config=json.loads((root/'config.json').read_text());spec=json.loads((root/'case-spec.json').read_text());control=json.loads((root/'controller.json').read_text())
    case_id=config['selected_case_id']
    if spec.get('case_id')!=case_id:raise ValueError('Exact route case differs')
    if not attempt.is_dir() or any((attempt/name).exists() for name in ('trace.jsonl','video_frames.jsonl','original-route-observations.json','original-route-receipt.json','result.json')):
        raise ValueError('Fresh materialized Native attempt required')
    packet=load_review(review_path,source_root,case_id)
    if (packet['site']['intervening_street']['designation']!=spec['street_class'] or packet['itinerary']['route_use']!=spec['route_use'] or packet['enroute_purpose']['kind']!=spec['enroute_purpose']):
        raise ValueError('Reviewed route comparison variable differs')
    by_path={row['path']:row for row in packet['source_provenance']['files']}
    opendrive=packet.get('opendrive_source_path')
    if not opendrive or opendrive not in by_path:raise ValueError('Original OpenDRIVE source not inventoried')
    poses=packet.get('cameras',{})
    if set(poses)!=set(CAMERAS):raise ValueError('All four reviewed original camera poses required')
    for name,row in poses.items():
        if len(row.get('location_xyz_m',[]))!=3 or len(row.get('pitch_yaw_roll_deg',[]))!=3:
            raise ValueError('Original camera pose incomplete: '+name)
    shutil.copy2(review_path,attempt/'reviewed-route.json')
    for source in by_path.values():
        target=attempt/'reviewed-sources'/source['path'];target.parent.mkdir(parents=True,exist_ok=True)
        shutil.copy2(source_root/source['path'],target)
    if 'SCENARIO_PIPELINE_OUTPUT_ROOT' not in os.environ:raise ValueError('Runtime output root required before Native import')
    import carla
    from worker_exchange.native_output import FrameMap,seal_capture
    from worker_exchange.world_restore import snapshot,restore
    client=carla.Client(host,int(port));client.set_timeout(30);prior=snapshot(client)
    cameras={};queues={};encoders={};handle=None;frame_map=None;failure=None;restored=False
    try:
        world=client.generate_opendrive_world((source_root/opendrive).read_text())
        live_sha=hashlib.sha256(world.get_map().to_opendrive().encode()).hexdigest()
        if live_sha!=by_path[opendrive]['sha256']:raise ValueError('Native OpenDRIVE readback differs from reviewed source')
        settings=world.get_settings();settings.synchronous_mode=True;settings.fixed_delta_seconds=.05;settings.no_rendering_mode=False;world.apply_settings(settings)
        handle=configure(world,carla,packet,float(control['target_speed_mps']))
        for name,(width,height) in CAMERAS.items():
            queues[name]=Queue();cameras[name]=camera(world,carla,poses[name],name,queues[name]);encoders[name]=encoder(attempt/(name+'.mkv'),width,height)
        frame_map=FrameMap(attempt/'video_frames.jsonl');observations=[]
        with (attempt/'trace.jsonl').open('x',buffering=1) as trace:
            for _ in range(900):
                step(handle,carla)
                frame=world.tick();time_s=float(world.get_snapshot().timestamp.elapsed_seconds)
                frame_map.append(frame,time_s)
                row=sample(world,handle,packet,frame,time_s)
                observations.append(row)
                trace.write(json.dumps({'frame':frame,'time_s':time_s,'actor_id':row['ego_actor_id'],'position_m':row['position_xy_m']},allow_nan=False)+'\n')
                for name in CAMERAS:encoders[name].stdin.write(bytes(image(queues[name],frame).raw_data))
        for process in encoders.values():
            process.stdin.close()
            if process.wait(timeout=120)!=0:raise RuntimeError('Four-view truck-route encoder failed')
        frame_map.close()
        data={'assignment_id':root.name,'case_id':case_id,'original_trace_id':'Native:'+sha(attempt/'trace.jsonl'),'diagnostic_fixture':False,
            'site_source_sha256':sha(review_path),'site':packet['site'],'itinerary':packet['itinerary'],'enroute_purpose':packet['enroute_purpose'],'fps':20,'frames':observations}
        write(attempt/'original-route-observations.json',data)
        write(attempt/'original-route-receipt.json',{'case_id':case_id,'fps':20,'frame_count':900,'diagnostic_fixture':False,'source_sha256':sha(attempt/'original-route-observations.json'),'review_sha256':sha(review_path)})
    except BaseException as error:failure=error
    finally:
        if frame_map is not None and not frame_map.stream.closed:frame_map.close()
        for process in encoders.values():
            if process.poll() is None:process.kill();process.wait()
        for actor in cameras.values():
            try:actor.stop()
            finally:actor.destroy()
        if handle is not None:
            try:teardown(handle)
            except BaseException as error:failure=failure or error
        try:restored=bool(restore(client,prior)['restored'])
        except BaseException as error:failure=failure or error
    write(attempt/'native-run-status.json',{'restored':restored,'capture_complete':failure is None,'errors':[repr(failure)] if failure else []})
    if failure or not restored:raise RuntimeError('Original truck-route capture or restoration failed') from failure
    write(attempt/'acquisition-provenance.json',{'provenance_kind':'native','diagnostic_fixture':False,'case_id':case_id,'review_sha256':sha(review_path)})
    seal_capture(attempt,frames=900,restoration={'restored':True},errors=[],encoder_exit_codes={name:0 for name in CAMERAS},context={'case_id':case_id,'review_sha256':sha(review_path),'legal_verdict_claimed':False})
    return {'case_id':case_id,'frame_count':900,'restored':True,'original_route_source_sha256':sha(attempt/'original-route-observations.json'),'physical_acceptance':False}

"""Bundled original CARLA vehicle route controller and readback."""
from __future__ import annotations

import math


def _target_yaw(dx: float, dy: float) -> float:
    return math.degrees(math.atan2(dy, dx))


def configure(world, carla, packet: dict, speed_mps: float):
    itinerary=packet['itinerary']
    points=itinerary['waypoints_xy_m']
    spawn=itinerary['spawn_xyz_m']
    if len(spawn)!=3 or not all(math.isfinite(float(value)) for value in spawn):
        raise ValueError('Original vehicle spawn missing')
    dx=points[1][0]-points[0][0];dy=points[1][1]-points[0][1]
    blueprint=world.get_blueprint_library().find(itinerary['vehicle_blueprint'])
    if blueprint is None or not blueprint.id.startswith('vehicle.'):
        raise ValueError('Original motor vehicle blueprint missing')
    pose=carla.Transform(carla.Location(x=float(spawn[0]),y=float(spawn[1]),z=float(spawn[2])),carla.Rotation(yaw=_target_yaw(dx,dy)))
    vehicle=world.try_spawn_actor(blueprint,pose)
    if vehicle is None or not vehicle.type_id.startswith('vehicle.'):
        raise RuntimeError('Original motor vehicle spawn failed')
    vehicle.set_autopilot(False)
    protocol=packet.get('activity_protocol') if packet['enroute_purpose']['kind']!='none' else None
    prop=None
    if protocol:
        prop_bp=world.get_blueprint_library().find(protocol['prop_blueprint'])
        if prop_bp is None:raise ValueError('Reviewed activity prop blueprint missing')
        origin=protocol['premises_xyz_m'] if protocol['kind'] in ('pick_up','essential_use') else spawn
        prop=world.try_spawn_actor(prop_bp,carla.Transform(carla.Location(x=float(origin[0]),y=float(origin[1]),z=float(origin[2]))))
        if prop is None:raise RuntimeError('Original activity prop spawn failed')
    return {'vehicle':vehicle,'prop':prop,'protocol':protocol,'activity_ticks':None,'activity_event':False,
        'points':points,'next_index':1,'speed_mps':float(speed_mps)}


def step(handle, carla):
    vehicle=handle['vehicle'];points=handle['points'];index=handle['next_index']
    location=vehicle.get_transform().location
    while index<len(points)-1 and math.hypot(points[index][0]-location.x,points[index][1]-location.y)<3.0:
        index+=1
    handle['next_index']=index
    protocol=handle['protocol']
    if protocol:
        if protocol['kind']=='delivery' and (handle['activity_ticks'] is None or handle['activity_ticks']<12):
            handle['prop'].set_transform(carla.Transform(vehicle.get_transform().location))
        premises=protocol['premises_xyz_m']
        distance=math.hypot(premises[0]-location.x,premises[1]-location.y)
        if handle['activity_ticks'] is None and distance<=4.0:
            handle['activity_ticks']=0
        if handle['activity_ticks'] is not None and handle['activity_ticks']<20:
            handle['activity_ticks']+=1
            vehicle.apply_control(carla.VehicleControl(throttle=0.0,steer=0.0,brake=1.0))
            if handle['activity_ticks']==12:
                speed=vehicle.get_velocity()
                if math.hypot(speed.x,speed.y)>1.0:
                    raise ValueError('Vehicle did not physically stop for reviewed activity')
                prop=handle['prop']
                if not prop or not prop.is_alive:raise RuntimeError('Original activity prop missing')
                moved=vehicle.get_transform().location if protocol['kind'] in ('pick_up','essential_use') else carla.Location(x=float(premises[0]),y=float(premises[1]),z=float(premises[2]))
                prop.set_transform(carla.Transform(moved))
                handle['activity_event']=True
            return
        if handle['activity_ticks'] is not None and handle['activity_ticks']>=20 and protocol['kind'] in ('pick_up','essential_use'):
            handle['prop'].set_transform(carla.Transform(vehicle.get_transform().location))
    target=points[index]
    desired=_target_yaw(target[0]-location.x,target[1]-location.y)
    yaw=vehicle.get_transform().rotation.yaw
    error=(desired-yaw+180.0)%360.0-180.0
    speed=vehicle.get_velocity();speed_now=math.sqrt(speed.x**2+speed.y**2+speed.z**2)
    throttle=max(0.0,min(.55,.24*(handle['speed_mps']-speed_now)))
    brake=0.0 if speed_now<=handle['speed_mps'] else min(.5,.18*(speed_now-handle['speed_mps']))
    vehicle.apply_control(carla.VehicleControl(throttle=throttle,steer=max(-.8,min(.8,error/45.0)),brake=brake))


def sample(world, handle, packet: dict, frame: int, time_s: float) -> dict:
    vehicle=handle['vehicle']
    if not vehicle.is_alive:
        raise RuntimeError('Original ego vehicle no longer alive')
    transform=vehicle.get_transform();position=transform.location
    waypoint=world.get_map().get_waypoint(position,project_to_road=False)
    if waypoint is None:
        raise ValueError('Original vehicle is outside reviewed roadway')
    road_id=int(waypoint.road_id)
    routes=packet['site']['truck_routes'];street=packet['site']['intervening_street']
    if road_id==int(street['road_id']):designation=street['designation']
    elif road_id in (int(routes['origin']['road_id']),int(routes['destination']['road_id'])):designation='truck_route'
    else:raise ValueError('Original vehicle reached unreviewed road identity')
    activity=None
    if handle['activity_event']:
        prop=handle['prop']
        if not prop or not prop.is_alive:
            raise RuntimeError('Original activity prop disappeared')
        where=prop.get_transform().location
        if math.hypot(where.x-position.x,where.y-position.y)>5.0 and packet['enroute_purpose']['kind'] in ('pick_up','essential_use'):
            raise ValueError('Original pickup/essential prop transfer not observed')
        activity=packet['enroute_purpose']['kind']
        handle['activity_event']=False
    return {'frame':int(frame),'time_s':float(time_s),'ego_actor_id':int(vehicle.id),
        'position_xy_m':[float(position.x),float(position.y)],'road_id':road_id,
        'street_designation':designation,'activity_kind':activity,'activity_prop_actor_id':handle['prop'].id if handle['prop'] else None,'observation_source':'original_native_snapshot'}


def teardown(handle):
    vehicle=handle['vehicle']
    if handle.get('prop') is not None and handle['prop'].is_alive:handle['prop'].destroy()
    if vehicle.is_alive:vehicle.destroy()

"""Source-bound measurement for LVMC 11.48.060, without legal classification."""
from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path

KINDS = ('none', 'pick_up', 'delivery', 'essential_use')
STREETS = ('truck_route', 'non_truck')


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def finite_xy(value: object) -> tuple[float, float]:
    if not isinstance(value, (list, tuple)) or len(value) != 2:
        raise ValueError('A route position needs two coordinates')
    x, y = float(value[0]), float(value[1])
    if not math.isfinite(x) or not math.isfinite(y):
        raise ValueError('A route position must be finite')
    return x, y


def load_review(path: Path, source_root: Path, case_id: str, diagnostic: bool = False) -> dict:
    """Require reviewed original route status before Native mutation."""
    packet = json.loads(path.read_text())
    if packet.get('format') != 'worker-reviewed-truck-route-site' or packet.get('case_id') != case_id:
        raise ValueError('Route review identity differs')
    if bool(packet.get('diagnostic_fixture')) != diagnostic:
        raise ValueError('Synthetic route source cannot become original evidence')
    provenance = packet.get('source_provenance', {})
    if not diagnostic and (provenance.get('kind') != 'original_reviewed_site'
            or not provenance.get('reviewer') or not provenance.get('citation')):
        raise ValueError('Original route needs independent reviewer and citation')
    source_files = provenance.get('files', [])
    if not source_files:
        raise ValueError('Authoritative source files missing')
    for source in source_files:
        if not isinstance(source, dict) or not source.get('path') or not source.get('sha256'):
            raise ValueError('Unversioned original route source')
        item = (source_root / source['path']).resolve()
        if source_root.resolve() not in item.parents or not item.is_file() or sha(item) != source['sha256']:
            raise ValueError('Original route source missing or hash differs')
    site = packet.get('site', {})
    if site.get('municipal_jurisdiction_reviewed') is not True:
        raise ValueError('Municipal jurisdiction unreviewed')
    if site.get('chapter_scope_reviewed') is not True:
        raise ValueError('Chapter actor and vehicle scope unreviewed')
    hashes = {row['sha256'] for row in source_files}
    routes = site.get('truck_routes', {})
    if not all(isinstance(routes.get(key), dict) and routes[key].get('designation_source_sha256')
               and routes[key].get('road_id') for key in ('origin', 'destination')):
        raise ValueError('Both authoritative truck route designations required')
    if any(type(routes[key]['road_id']) is not int or routes[key]['designation_source_sha256'] not in hashes for key in ('origin', 'destination')):
        raise ValueError('Original truck-route identity or cited designation source invalid')
    if routes['origin']['road_id'] == routes['destination']['road_id']:
        raise ValueError('Distinct truck routes required')
    street = site.get('intervening_street', {})
    if street.get('designation') not in STREETS or not street.get('road_id') or not street.get('designation_source_sha256'):
        raise ValueError('Intervening street designation source missing')
    if type(street['road_id']) is not int or street['designation_source_sha256'] not in hashes:
        raise ValueError('Original connector identity or cited designation source invalid')
    if site.get('governing_controls_reviewed') is not True:
        raise ValueError('Route controls unreviewed')
    itinerary = packet.get('itinerary', {})
    if itinerary.get('route_use') not in ('through', 'local'):
        raise ValueError('Route-use target missing')
    waypoints = itinerary.get('waypoints_xy_m', [])
    if len(waypoints) < 3:
        raise ValueError('Original route needs at least three waypoints')
    for point in waypoints:
        finite_xy(point)
    if not itinerary.get('origin_on_truck_route') or not itinerary.get('entered_intervening_street'):
        raise ValueError('Route origin and intervening street missing')
    if itinerary['route_use'] == 'through' and not itinerary.get('destination_on_truck_route'):
        raise ValueError('Through route needs destination truck route')
    if itinerary['route_use'] == 'local' and (itinerary.get('destination_on_truck_route') or not itinerary.get('local_destination_reviewed')):
        raise ValueError('Local control needs reviewed local endpoint')
    purpose = packet.get('enroute_purpose', {})
    if purpose.get('kind') not in KINDS:
        raise ValueError('Unknown enroute purpose')
    if purpose['kind'] != 'none' and (not purpose.get('required_enroute_reviewed')
            or not purpose.get('premises_source_sha256') or not purpose.get('activity_source_sha256')):
        raise ValueError('Exception needs independently reviewed necessity, premises and activity')
    if purpose['kind'] != 'none' and (purpose['premises_source_sha256'] not in hashes or purpose['activity_source_sha256'] not in hashes):
        raise ValueError('Original enroute premises or activity source not cited')
    if purpose['kind'] == 'none' and purpose.get('required_enroute_reviewed'):
        raise ValueError('No-purpose control cannot assert an exception')
    if purpose['kind'] != 'none' and not diagnostic:
        protocol = packet.get('activity_protocol', {})
        if (protocol.get('kind') != purpose['kind'] or not protocol.get('reviewed')
                or not protocol.get('source_sha256') or not protocol.get('prop_blueprint')
                or not protocol['prop_blueprint'].startswith('static.prop.')
                or len(protocol.get('premises_xyz_m', [])) != 3
                or protocol.get('source_sha256') not in {row['sha256'] for row in source_files}):
            raise ValueError('Original required-enroute activity construction missing')
        for value in protocol['premises_xyz_m']:
            if not math.isfinite(float(value)):
                raise ValueError('Original premises position invalid')
    return packet


def measure(source: Path) -> dict:
    packet = json.loads(source.read_text())
    case_id = packet.get('case_id')
    frames = packet.get('frames', [])
    if not case_id or len(frames) < 3 or packet.get('fps') != 20:
        raise ValueError('Original 20 Hz route frames missing')
    seen = []
    prior_frame = -1
    prior_time = -1.0
    for row in frames:
        frame, time_s = row.get('frame'), row.get('time_s')
        if not isinstance(frame, int) or frame <= prior_frame or not isinstance(time_s, (int, float)) or time_s <= prior_time:
            raise ValueError('Nonmonotonic original route frame/time')
        if not math.isfinite(time_s) or not isinstance(row.get('ego_actor_id'), int):
            raise ValueError('Original route identity/time invalid')
        finite_xy(row.get('position_xy_m'))
        if row.get('road_id') is None or row.get('street_designation') not in STREETS:
            raise ValueError('Original road identity/status missing')
        seen.append(row['road_id'])
        prior_frame, prior_time = frame, time_s
    site = packet.get('site', {})
    routes = site.get('truck_routes', {})
    street = site.get('intervening_street', {})
    origin = routes.get('origin', {}).get('road_id')
    middle = street.get('road_id')
    destination = routes.get('destination', {}).get('road_id')
    if not origin or not middle or not destination or origin not in seen or middle not in seen:
        raise ValueError('Original origin and intervening road samples missing')
    first_middle = seen.index(middle)
    if seen.index(origin) >= first_middle:
        raise ValueError('Origin must precede connecting road')
    complete = destination in seen[first_middle + 1:]
    if packet.get('itinerary', {}).get('route_use') == 'through' and not complete:
        raise ValueError('Original through passage is incomplete')
    if packet.get('itinerary', {}).get('route_use') == 'local' and complete:
        raise ValueError('Local control unexpectedly reaches destination truck route')
    if not any(row.get('road_id') == middle and row.get('street_designation') == street.get('designation') for row in frames):
        raise ValueError('Connecting road designation not observed')
    purpose = packet.get('enroute_purpose', {})
    kind = purpose.get('kind')
    activities = [row for row in frames if row.get('activity_kind') == kind and row.get('road_id') == middle]
    if kind != 'none' and (not activities or not purpose.get('required_enroute_reviewed')):
        raise ValueError('Required enroute activity not source-observed')
    if kind != 'none' and packet.get('diagnostic_fixture') is False and any(
            type(row.get('activity_prop_actor_id')) is not int or
            row.get('observation_source') != 'original_native_snapshot' for row in activities):
        raise ValueError('Original activity prop readback missing')
    return {'origin_truck_route_observed': True, 'intervening_street_observed': True,
        'destination_truck_route_observed': complete, 'intervening_designation': street['designation'],
        'enroute_purpose_kind': kind, 'enroute_activity_observed': bool(activities),
        'required_enroute_reviewed': bool(purpose.get('required_enroute_reviewed')),
        'sample_count': len(frames), 'first_native_frame': frames[0]['frame'],
        'last_native_frame': frames[-1]['frame']}

"""Saved-only source-bound route finalizer; no legal verdict."""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path

from route_measure import measure

CAMERAS = ('overview','approach','reference_corner','driver_reference')


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def required(root: Path, name: str) -> Path:
    path = root/name
    if not path.is_file():
        raise ValueError('Missing required source: '+name)
    return path


def rows(path: Path) -> list[dict]:
    return [json.loads(line) for line in path.read_text().splitlines() if line]


def measure_route(source: Path) -> dict:
    return measure(source)


def measure_scope(source: Path) -> dict:
    return measure(source)


def measure_pickup(source: Path) -> dict:
    m=measure(source);return {'pick_up_required_enroute':m['enroute_purpose_kind']=='pick_up' and m['enroute_activity_observed'] and m['required_enroute_reviewed']}


def measure_delivery(source: Path) -> dict:
    m=measure(source);return {'delivery_required_enroute':m['enroute_purpose_kind']=='delivery' and m['enroute_activity_observed'] and m['required_enroute_reviewed']}


def measure_essential(source: Path) -> dict:
    m=measure(source);return {'essential_use_required_enroute':m['enroute_purpose_kind']=='essential_use' and m['enroute_activity_observed'] and m['required_enroute_reviewed']}


def measure_route_control(source: Path) -> dict:
    m=measure(source);return {'local_or_designated_control':not m['destination_truck_route_observed'] or m['intervening_designation']=='truck_route'}


def analyze(attempt: Path, output: Path) -> dict:
    attempt,output=Path(attempt).resolve(),Path(output).resolve()
    config=json.loads(required(attempt,'config.json').read_text())
    case_id=config['selected_case_id']
    source=required(attempt,'original-route-observations.json')
    packet=json.loads(source.read_text())
    receipt=json.loads(required(attempt,'original-route-receipt.json').read_text())
    if (packet.get('case_id')!=case_id or receipt.get('case_id')!=case_id
            or receipt.get('source_sha256')!=sha(source) or receipt.get('fps')!=20):
        raise ValueError('Original route receipt identity or source hash differs')
    measurement=measure_route(source)
    frames=packet['frames']
    if receipt.get('frame_count')!=len(frames):
        raise ValueError('Original route frame count differs')
    frame_map=rows(required(attempt,'video_frames.jsonl'))
    trace=rows(required(attempt,'trace.jsonl'))
    if packet.get('diagnostic_fixture') is False and packet.get('original_trace_id')!='Native:'+sha(attempt/'trace.jsonl'):
        raise ValueError('Original route packet trace source differs')
    if len(frames)!=len(frame_map) or len(frames)!=len(trace):
        raise ValueError('Original route streams differ')
    for index,(frame,mapped,row) in enumerate(zip(frames,frame_map,trace)):
        if (mapped.get('video_frame')!=index or frame.get('frame')!=mapped.get('carla_frame')
                or frame['frame']!=mapped.get('native_frame') or row.get('frame')!=frame['frame']
                or abs(frame['time_s']-mapped.get('time_s',-1))>1e-4
                or abs(frame['time_s']-row.get('time_s',-1))>1e-4):
            raise ValueError('Original route frame/time join differs')
    for camera in CAMERAS: required(attempt,camera+'.mkv')
    description=config['case']['recording_description']
    channels=attempt/'channels';channels.mkdir(exist_ok=False)
    site=packet['site'];purpose=packet['enroute_purpose']
    values={
        'municipal_route_designation':lambda frame:{'municipal_jurisdiction_reviewed':site['municipal_jurisdiction_reviewed'],'truck_routes':site['truck_routes'],'intervening_street':site['intervening_street']},
        'ego_route_history':lambda frame:{'road_id':frame['road_id'],'street_designation':frame['street_designation'],'position_xy_m':frame['position_xy_m'],'ego_actor_id':frame['ego_actor_id']},
        'enroute_context':lambda frame:{'kind':purpose['kind'],'required_enroute_reviewed':purpose.get('required_enroute_reviewed',False),'activity_kind':frame.get('activity_kind'),'premises_source_sha256':purpose.get('premises_source_sha256')},
        'governing_controls':lambda frame:{'controls_reviewed':site['governing_controls_reviewed'],'chapter_scope_reviewed':site['chapter_scope_reviewed']}}
    evidence=[]
    for channel in description['channels']:
        name=channel['name']
        if name not in values: raise ValueError('Unimplemented route channel '+name)
        ref='channels/'+name+'.jsonl'
        with (attempt/ref).open('x') as stream:
            for frame in frames:
                stream.write(json.dumps({'time_s':frame['time_s'],'value':values[name](frame)},separators=(',',':'))+'\n')
        evidence.append({'name':name,'unit':channel['unit'],'reference':ref})
    context='channels/reviewed_truck_route_site.json'
    (attempt/context).write_text(json.dumps({'reviewed_truck_route_site':{'site_source_sha256':packet['site_source_sha256'],'statutory_judgment':'unresolved'}})+'\n')
    evidence.append({'name':'reviewed_truck_route_site','unit':'source','reference':context})
    native={'case_id':case_id,'measured_values':{'route':measurement},'target_checks':[{'target':'source-bound between-route passage and enroute context','requested':True,'measured':True,'method':'measure_route','tolerance':0,'matched':True,'physical_cause_confirmed':False,'cause_evidence':['original-route-observations.json']}],
        'setup_confirmed':False,'behavior_attempted':False,'maneuver_completed':False,'termination_reason':'Saved route measurement; physical and legal review pending','physical_failure_flags':[],'trace_reference':'trace.jsonl','video_references':[name+'.mkv' for name in CAMERAS],'video_frame_map_reference':'video_frames.jsonl','recording_description':description,'recording_evidence':evidence,'realized_observables':{}}
    (attempt/'result.json').write_text(json.dumps(native,indent=2,allow_nan=False)+'\n')
    report={'format':'worker-analysis-report','case_id':case_id,'measurements':{key:{'method':method.__name__,'sources':{'original-route-observations.json':sha(source),'original-route-receipt.json':sha(attempt/'original-route-receipt.json')},'value':method(source)} for key,method in [('scope',measure_scope),('pickup_context',measure_pickup),('delivery_context',measure_delivery),('essential_context',measure_essential),('route_control',measure_route_control)]},'limitations':['Original route designations, premises activity, Native motion and legal required-enroute judgment require independent review.']}
    output.write_text(json.dumps(report,indent=2,allow_nan=False)+'\n')
    return report


def main():
    parser=argparse.ArgumentParser();parser.add_argument('--attempt',type=Path,required=True);parser.add_argument('--output',type=Path,required=True);args=parser.parse_args();analyze(args.attempt,args.output)

if __name__=='__main__':main()

